const crypto = require('crypto');
const EventEmitter = require('events');

const CHUNK_HEADER_SIZE = 12;
const MAX_PAYLOAD_SIZE = 0x7FFFFFFF;
const ENCRYPTION_OVERHEAD = 16; // AES-GCM auth tag
const IV_LENGTH = 12;

class EncryptedStorageDriver extends EventEmitter {
  constructor(options = {}) {
    super();
    this.key = options.key || crypto.randomBytes(32);
    this.algorithm = 'aes-256-gcm';
    this.pageSize = options.pageSize || 4096;
    this.bufferPool = Buffer.allocUnsafe(options.poolSize || 65536);
    this.writeOffset = 0;
    this.metadata = new Map();
  }

  /**
   * Computes the required buffer allocation size for an encrypted record.
   * Layout: [4-byte totalLen][4-byte flags][4-byte fieldCount][IV][ciphertext][authTag]
   */
  computeAllocationSize(fields) {
    let payloadSize = 0;
    for (const field of fields) {
      // Each field: 2-byte name length + name + 4-byte value length + value
      payloadSize += 2 + Buffer.byteLength(field.name, 'utf8') + 4 + field.value.length;
    }
    // Total = header + IV + encrypted(payload) + auth tag
    // encrypted payload is same size as payload for AES-GCM (stream cipher)
    const totalSize = CHUNK_HEADER_SIZE + IV_LENGTH + payloadSize + ENCRYPTION_OVERHEAD;
    return totalSize;
  }

  /**
   * Validates that the computed size won't cause issues.
   * Returns the safe allocation size or throws.
   */
  validateAndComputeSize(fields, reservedBytes) {
    const baseSize = this.computeAllocationSize(fields);
    // reservedBytes accounts for alignment padding and page boundary overhead
    // Ensure reserved doesn't exceed base to prevent underflow
    if (reservedBytes > baseSize) {
      throw new RangeError('Reserved bytes exceed record size');
    }
    const netAllocation = baseSize - reservedBytes;

    if (netAllocation > MAX_PAYLOAD_SIZE || netAllocation < CHUNK_HEADER_SIZE + IV_LENGTH + ENCRYPTION_OVERHEAD) {
      throw new RangeError('Record exceeds maximum payload size or is too small');
    }
    return baseSize;
  }

  /**
   * Encrypts and writes a record to the internal buffer pool.
   */
  writeRecord(fields, options = {}) {
    const reservedBytes = options.reservedBytes || 0;
    if (reservedBytes < 0 || !Number.isInteger(reservedBytes)) {
      throw new TypeError('reservedBytes must be a non-negative integer');
    }
    const allocSize = this.validateAndComputeSize(fields, reservedBytes);

    // Ensure buffer pool has space
    if (this.writeOffset + allocSize > this.bufferPool.length) {
      this.flush();
    }

    // Serialize the payload
    let payloadSize = 0;
    for (const field of fields) {
      payloadSize += 2 + Buffer.byteLength(field.name, 'utf8') + 4 + field.value.length;
    }

    const payload = Buffer.allocUnsafe(payloadSize);
    let offset = 0;
    for (const field of fields) {
      const nameLen = Buffer.byteLength(field.name, 'utf8');
      payload.writeUInt16BE(nameLen, offset); offset += 2;
      payload.write(field.name, offset, nameLen, 'utf8'); offset += nameLen;
      payload.writeUInt32BE(field.value.length, offset); offset += 4;
      field.value.copy(payload, offset); offset += field.value.length;
    }

    // Encrypt
    const iv = crypto.randomBytes(IV_LENGTH);
    const cipher = crypto.createCipheriv(this.algorithm, this.key, iv);
    const encrypted = Buffer.concat([cipher.update(payload), cipher.final()]);
    const authTag = cipher.getAuthTag();

    // Write to buffer pool using allocSize for bounds
    const record = this.bufferPool.slice(this.writeOffset, this.writeOffset + allocSize);
    let pos = 0;

    // Header
    record.writeUInt32BE(allocSize, pos); pos += 4;
    record.writeUInt32BE(options.flags || 0, pos); pos += 4;
    record.writeUInt32BE(fields.length, pos); pos += 4;

    // IV
    iv.copy(record, pos); pos += IV_LENGTH;

    // Ciphertext
    encrypted.copy(record, pos); pos += encrypted.length;

    // Auth tag
    authTag.copy(record, pos); pos += ENCRYPTION_OVERHEAD;

    this.writeOffset += allocSize;
    this.metadata.set(this.metadata.size, { offset: this.writeOffset - allocSize, size: allocSize });

    return { id: this.metadata.size - 1, size: allocSize };
  }

  flush() {
    this.emit('flush', this.bufferPool.slice(0, this.writeOffset));
    this.writeOffset = 0;
  }

  readRecord(id) {
    const meta = this.metadata.get(id);
    if (!meta) throw new Error('Record not found');

    const record = this.bufferPool.slice(meta.offset, meta.offset + meta.size);
    const totalLen = record.readUInt32BE(0);
    const flags = record.readUInt32BE(4);
    const fieldCount = record.readUInt32BE(8);

    let pos = CHUNK_HEADER_SIZE;
    const iv = record.slice(pos, pos + IV_LENGTH); pos += IV_LENGTH;
    const ciphertextLen = meta.size - CHUNK_HEADER_SIZE - IV_LENGTH - ENCRYPTION_OVERHEAD;
    const ciphertext = record.slice(pos, pos + ciphertextLen); pos += ciphertextLen;
    const authTag = record.slice(pos, pos + ENCRYPTION_OVERHEAD);

    const decipher = crypto.createDecipheriv(this.algorithm, this.key, iv);
    decipher.setAuthTag(authTag);
    const decrypted = Buffer.concat([decipher.update(ciphertext), decipher.final()]);

    const fields = [];
    let dpos = 0;
    for (let i = 0; i < fieldCount; i++) {
      const nameLen = decrypted.readUInt16BE(dpos); dpos += 2;
      const name = decrypted.toString('utf8', dpos, dpos + nameLen); dpos += nameLen;
      const valueLen = decrypted.readUInt32BE(dpos); dpos += 4;
      const value = decrypted.slice(dpos, dpos + valueLen); dpos += valueLen;
      fields.push({ name, value });
    }

    return { fields, flags };
  }
}

module.exports = { EncryptedStorageDriver, CHUNK_HEADER_SIZE, MAX_PAYLOAD_SIZE };
